#include <stdio.h>
#include <stdlib.h>

/* Provided by the candidate in solution.c */
int primes_up_to(int n, int *out);

int main(void)
{
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    /* One slot per candidate is a safe over-estimate of the prime count. */
    size_t room = (n > 0) ? (size_t)n + 1 : 1;
    int *out = malloc(room * sizeof *out);
    if (out == NULL) {
        return 1;
    }

    int found = primes_up_to(n, out);
    printf("%d\n", found);
    for (int i = 0; i < found; i++) {
        printf("%d%s", out[i], (i + 1 < found) ? " " : "");
    }
    printf("\n");

    free(out);
    return 0;
}

